single.representative:
SELECT COUNT(*) FROM (
  SELECT Country FROM singer GROUP BY Country HAVING COUNT(*) > 2
) AS T

SELECT COUNT(*) FROM (
  SELECT Country FROM singer GROUP BY Country HAVING COUNT(Singer_ID) > 2
) AS countries_with_more_than_2_car_makers

